def fetch_task_data(task_id):
    base_url = "http://judges.ml.compas.ox.ac.uk/arc-settingsARC-Continual/"
    print(f"Fetching demos from demos endpoint...")

    # Try the demos endpoint
    try:
        r = httpx.get(f"{base_url}/{task_id}/demos", timeout=10)
        if r.status_code == 200:
            return r.json()
    except Exception as e:
        print(f"Error fetching demos: {e}")

    # Try a different format
    try:
        r = httpx.get(f"{base_url}/{task_id}?task=demos", timeout=10)
        if r.status_code == 200:
            return r.json()
    except Exception as e:
        print(f"Error fetching demos format 2: {e}")

    return None

